using UnityEditor;
using UnityEngine;
public class FixZombieCones { [MenuItem("Tools/Fix Zombie Detection Cones")] static void FixCones() { ZombieChaseAI[] zombies = Object.FindObjectsByType<ZombieChaseAI>(FindObjectsSortMode.None); int fixedCount = 0; foreach (var zombie in zombies) { Transform cone = null; foreach (var t in zombie.GetComponentsInChildren<Transform>(true)) { if (t.name == "DetectionCone") { cone = t; break; } } if (cone == null) { Debug.LogWarning($"No DetectionCone found under {zombie.name}", zombie); continue; } Renderer rend = cone.GetComponent<Renderer>(); if (rend == null) { Debug.LogWarning($"DetectionCone under {zombie.name} has no Renderer", zombie); continue; } SerializedObject so = new SerializedObject(zombie); SerializedProperty prop = so.FindProperty("detectionConeRenderer"); prop.objectReferenceValue = rend; so.ApplyModifiedProperties(); fixedCount++; } Debug.Log($"Fixed {fixedCount} zombie(s)."); } }